<mask id="tt-coreTrack"><rect x="510" y="570" width="220" height="160" fill="#fff"/><path d="M460 560 L620 480 L780 560 L620 640 Z" fill="#000"/></mask>
<filter id="tt-soft" x="-40%" y="-60%" width="180%" height="240%"><feGaussianBlur stdDeviation="17"/></filter>
</defs>

